/// A generic connection abstraction over any data provider (Plaid, Debank, etc.).
/// Each connection maps to a row in the `connections` table via (source_table, source_id).
#[derive(async_graphql::SimpleObject, Clone, Debug, PartialEq, Default)]
#[graphql(name = "Connection")]
#[graphql(complex)]
pub struct Connection {
    #[graphql(skip)]
    pub id: i64,
    /// Institution or display name for this provider connection.
    #[graphql(name = "name")]
    pub name: Option<String>,
    #[graphql(name = "owner")]
    pub owner: Owner,
    #[graphql(name = "isActive")]
    pub is_active: bool,
}

pub trait ConnectionResolvers {
    fn provider(
        &self,
        ctx: &async_graphql::Context<'_>,
    ) -> impl std::future::Future<Output = async_graphql::Result<Option<ConnectionProvider>>> + Send;
}

#[async_graphql::ComplexObject]
impl Connection {
    #[graphql(name = "id")]
    async fn id(&self) -> async_graphql::ID {
        crate::ids::GlobalId::new(crate::ids::GlobalIdType::Connection, self.id)
            .encoded_string()
            .into()
    }

    #[graphql(name = "provider")]
    async fn provider(&self, ctx: &async_graphql::Context<'_>) -> async_graphql::Result<Option<ConnectionProvider>> {
        nullable(ctx, async { ConnectionResolvers::provider(self, ctx).await }).await
    }
}

