/// A user authorized to access the dashboard.
#[derive(async_graphql::SimpleObject, Clone, Debug, PartialEq)]
#[graphql(name = "User")]
#[graphql(complex)]
pub struct User {
    #[graphql(skip)]
    pub id: i64,
    #[graphql(name = "email")]
    pub email: String,
    #[graphql(name = "role")]
    pub role: Role,
    #[graphql(name = "createdAt")]
    pub created_at: chrono::DateTime<chrono::Utc>,
}

#[async_graphql::ComplexObject]
impl User {
    #[graphql(name = "id")]
    async fn id(&self) -> async_graphql::ID {
        crate::ids::GlobalId::new(crate::ids::GlobalIdType::User, self.id)
            .encoded_string()
            .into()
    }
}

